<?php
require_once __DIR__ . '/../../includes/admin_auth.php';require_admin();$errors=[];if(is_post_request()){$title=post_string('title',150);$category=post_string('category',100);$description=post_string('description',3000);$status=isset($_POST['status'])?1:0;if(!verify_csrf_token($_POST['csrf_token']??null))$errors[]='Your form session expired. Please try again.';if($title==='')$errors[]='Title is required.';if($category==='')$errors[]='Category is required.';if(empty($_FILES['image'])||$_FILES['image']['error']===UPLOAD_ERR_NO_FILE)$errors[]='Please select an image.';$image=upload_image('image','gallery',$errors);if(!$errors){$insert=$pdo->prepare('INSERT INTO gallery(title,image,category,description,status) VALUES(:title,:image,:category,:description,:status)');$insert->execute(['title'=>$title,'image'=>$image,'category'=>$category,'description'=>$description?:null,'status'=>$status]);redirect('index.php');}}admin_header('Add Gallery Image','gallery/index.php');?><div class="card table-card"><div class="card-body p-4"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><div class="row g-3"><div class="col-md-6"><label class="form-label">Title *</label><input class="form-control" name="title" value="<?=old('title')?>" required></div><div class="col-md-6"><label class="form-label">Category *</label><input class="form-control" name="category" value="<?=old('category')?>" placeholder="Classes, Students, Projects..." required></div><div class="col-12"><label class="form-label">Image *</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required><small class="text-secondary">JPG, PNG, GIF or WebP; maximum 5 MB.</small></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="5"><?=old('description')?></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="status" id="status" checked><label class="form-check-label" for="status">Active</label></div></div></div><div class="mt-4"><button class="btn btn-primary" type="submit">Save Image</button><a class="btn btn-outline-secondary ms-2" href="index.php">Cancel</a></div></form></div></div><?php admin_footer();?>
